parametric [0, 1]:
double tau = t * T;
double h_fix = 0.012;
int n = (int)(tau / h_fix);
double rem = tau - (double)n * h_fix;
double a1 = th1;
double a2 = th2;
double w1 = 0.0;
double w2 = 0.0;
double gl = g / L;
for (int i = 0; i <= n; i++) {
  double h = (i < n) ? h_fix : rem;
  if (h <= 0.0) break;
  double d, cd, sd, den, A, B;
  double k1_a1 = w1, k1_a2 = w2;
  d = a1 - a2; cd = cos(d); sd = sin(d); den = 2.0 - cd * cd;
  A = -w2 * w2 * sd - 2.0 * gl * sin(a1);
  B = w1 * w1 * sd - gl * sin(a2);
  double k1_w1 = (A - B * cd) / den;
  double k1_w2 = (2.0 * B - A * cd) / den;
  double b1 = a1 + 0.5 * h * k1_a1, b2 = a2 + 0.5 * h * k1_a2;
  double u1 = w1 + 0.5 * h * k1_w1, u2 = w2 + 0.5 * h * k1_w2;
  double k2_a1 = u1, k2_a2 = u2;
  d = b1 - b2; cd = cos(d); sd = sin(d); den = 2.0 - cd * cd;
  A = -u2 * u2 * sd - 2.0 * gl * sin(b1);
  B = u1 * u1 * sd - gl * sin(b2);
  double k2_w1 = (A - B * cd) / den;
  double k2_w2 = (2.0 * B - A * cd) / den;
  b1 = a1 + 0.5 * h * k2_a1; b2 = a2 + 0.5 * h * k2_a2;
  u1 = w1 + 0.5 * h * k2_w1; u2 = w2 + 0.5 * h * k2_w2;
  double k3_a1 = u1, k3_a2 = u2;
  d = b1 - b2; cd = cos(d); sd = sin(d); den = 2.0 - cd * cd;
  A = -u2 * u2 * sd - 2.0 * gl * sin(b1);
  B = u1 * u1 * sd - gl * sin(b2);
  double k3_w1 = (A - B * cd) / den;
  double k3_w2 = (2.0 * B - A * cd) / den;
  b1 = a1 + h * k3_a1; b2 = a2 + h * k3_a2;
  u1 = w1 + h * k3_w1; u2 = w2 + h * k3_w2;
  double k4_a1 = u1, k4_a2 = u2;
  d = b1 - b2; cd = cos(d); sd = sin(d); den = 2.0 - cd * cd;
  A = -u2 * u2 * sd - 2.0 * gl * sin(b1);
  B = u1 * u1 * sd - gl * sin(b2);
  double k4_w1 = (A - B * cd) / den;
  double k4_w2 = (2.0 * B - A * cd) / den;
  a1 += (h / 6.0) * (k1_a1 + 2.0 * k2_a1 + 2.0 * k3_a1 + k4_a1);
  a2 += (h / 6.0) * (k1_a2 + 2.0 * k2_a2 + 2.0 * k3_a2 + k4_a2);
  w1 += (h / 6.0) * (k1_w1 + 2.0 * k2_w1 + 2.0 * k3_w1 + k4_w1);
  w2 += (h / 6.0) * (k1_w2 + 2.0 * k2_w2 + 2.0 * k3_w2 + k4_w2);
